239.     initial: FrameAllocView,
240.     reserved: Set<int>,
241. )
242.     requires
243.         initial.wf(),
244.         reserved.subset_of(initial.free_frames),
245.         forall|a: int| reserved.contains(a) ==> a % spec_page_size() == 0,
246.     ensures
247.         ({
248.             let pre = PhysMemView { initialized: false, frames: initial };
249.             let post = pre.spec_initialize(initial).spec_book_frames(reserved);
250.             &&& post.initialized
251.             &&& post.inv()
252.             &&& forall|a: int| reserved.contains(a)
253.                 ==> #[trigger] post.frames.allocated_frames.contains(a)
254.             &&& post.frames.allocated_frames.disjoint(post.frames.free_frames)
255.         }),
256. {
257.     let pre = PhysMemView { initialized: false, frames: initial };
258.     let established = pre.spec_initialize(initial);
259.     lemma_spec_initialize_establishes_inv(pre, initial);
260.     assert(established.initialized);
261.     assert(established.inv());
262.     assert(established.frames == initial);
263.     lemma_spec_book_frames_preserves_inv(established, reserved);
264.     let post = established.spec_book_frames(reserved);
265.     // Disjointness is part of `post.frames.wf()`, available from `post.inv()`.
266.     assert(post.initialized);
267.     assert(post.inv());
268.     assert(post.frames.wf());
269. }
